  insert into questions (chapter_id, type, category, source, difficulty, stem_md, options_json, answer_key_md, marks, family, explanation_md)
  values
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the primary driving force for atoms to form chemical bonds?', '["To increase their total energy.","To become radioactive.","To achieve a stable noble gas electronic configuration.","To increase the number of protons."]'::jsonb, 'C', 1, '404b85d2a11b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom forms three covalent bonds. It most likely needs:', '["Three electrons for stability","Two electrons for stability","One electron for stability","Four electrons for stability"]'::jsonb, 'A', 1, 'bdc1eb07db88', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which statement best explains the formation of ionic compounds?', '["Like charges attract each other","Oppositely charged ions attract each other","Neutrons attract electrons","Protons are exchanged"]'::jsonb, 'B', 1, '234559d498ae', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which rule states that atoms tend to gain, lose, or share electrons to have eight electrons in their valence shell?', '["Pauli exclusion principle","Duplet rule","Hund’s rule","Octet rule"]'::jsonb, 'D', 1, 'a04f24f7a1c3', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following is a characteristic property of ionic compounds?', '["Low melting points.","High electrical conductivity in the solid state.","High melting points and brittleness.","Solubility only in organic solvents."]'::jsonb, 'C', 1, 'fe4bcc4209e6', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which type of bond is responsible for the high electrical and thermal conductivity of metals?', '["Covalent bond.","Metallic bond","Hydrogen bond.","Ionic bond."]'::jsonb, 'B', 1, '093d1b97a6a3', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What determines the strength of an ionic bond?', '["The number of neutrons.","The color of the crystal.","The magnitude of the charges on the ions and the distance between them.","The atomic mass of the elements."]'::jsonb, 'C', 1, 'aef38d4fc593', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the formation of a covalent bond, what happens to the energy of the system?', '["It disappears.","It remains unchanged.","It increases.","It decreases to reach a stable energy minimum."]'::jsonb, 'D', 1, '66a5b97d1ff4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Electropositive elements are typically:', '["Metals","Noble gases","Non-metals.","Metalloids"]'::jsonb, 'A', 1, '6e78b8aeb20a', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which substance would have the highest melting point?', '["CH₄","NaCl","H₂O","O₂"]'::jsonb, 'B', 1, '29df089465cd', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Covalent compounds usually have:', '["A rigid lattice structure.","Ionic conductivity.","High boiling points.","Low boiling points due to weak intermolecular forces between molecules."]'::jsonb, 'D', 1, '53527169278d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Atoms with high electronegativity are more likely to form:', '["Cations.","Metallic bonds.","Anions.","Nothing."]'::jsonb, 'C', 1, '0ece0aa9da72', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the formation of MgO, what charge do the ions acquire?', '["+1, -1","+2, -2","+1, -2","0, 0"]'::jsonb, 'B', 1, '33bf8f5960d9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What represents the "cloud" in metallic bonding?', '["The neutrons.","The empty orbitals.","The protons.","The valence electrons that are no longer associated with a single nucleus."]'::jsonb, 'D', 1, 'adac6ea8a5bb', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is it that covalent bonds are generally strong?', '["Because shared electrons are held tightly by two positively charged nuclei.","Because they involve transfer.","Because they are large.","Because they only occur in solids."]'::jsonb, 'A', 1, '650153308703', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following substances would conduct electricity as a solid?', '["NaCl","Copper","Diamond","H₂O"]'::jsonb, 'B', 1, '1f0f5a5f6ba0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is fluorine highly reactive?', '["It has no valence electrons","It easily loses seven electrons","It has a complete octet","It needs one electron to complete its octet"]'::jsonb, 'D', 1, '0573c5a59bdc', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is electron transfer unlikely between two oxygen atoms?', '["Both atoms tend to gain electrons rather than lose them","Oxygen has no valence electrons","Oxygen atoms are metals","Oxygen atoms already have complete octets"]'::jsonb, 'A', 1, 'dfb61f4f6952', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student says, “Every bond involves electron transfer.” Which substance proves the statement incorrect?', '["NaCl","MgO","H₂O","KCl"]'::jsonb, 'C', 1, '543330021105', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does hydrogen form one covalent bond, but oxygen usually forms two?', '["Oxygen is heavier than hydrogen","Hydrogen needs one electron, and oxygen needs two electrons for stability","Oxygen has fewer electrons","Hydrogen forms only ionic bonds"]'::jsonb, 'B', 1, 'e166665b4db9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does the melting point of magnesium oxide (MgO) significantly exceed that of sodium chloride (NaCl)?', '["The lattice energy of MgO is much higher due to the greater electrostatic attraction between +2/-2 ions compared to +1/-1 ions.","MgO is a covalent compound.","NaCl is a metal.","Mg and O are smaller than Na and Cl."]'::jsonb, 'A', 1, '9c4ef2d4ddf5', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the molecule BF₃, the Boron atom is said to be "electron-deficient." What does this mean?', '["It has 8 valence electrons.","It has only 6 valence electrons, meaning it does not satisfy the octet rule.","It has 10 valence electrons.","It is a metal."]'::jsonb, 'B', 1, 'a3606b499abd', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When an atom forms a covalent bond, what is happening to the atomic orbitals?', '["They expand to infinite size.","They are destroyed.","They become ionic.","They overlap to create a region of space where electrons are likely to be shared."]'::jsonb, 'D', 1, '976cd5d45c0e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of these is a non-directional force?', '["The covalent bond between C and H.","The metallic bond between Na atoms.","The electrostatic attraction in an ionic lattice.","Both B and C."]'::jsonb, 'D', 1, '2e31119ac592', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What happens to the electronegativity difference as you go from an ionic to a covalent bond?', '["It becomes negative.","It increases.","It stays the same.","It decreases."]'::jsonb, 'D', 1, '34461731f4de', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom X loses one electron while atom Y gains one electron. Which statement is correct?', '["Both become negatively charged","X becomes a cation, and Y becomes an anion","Both become positively charged","X becomes an anion, and Y becomes a cation"]'::jsonb, 'B', 1, '1981fbf6065b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You are given an unknown substance X. It has a very high melting point, is brittle, and does not conduct electricity as a solid. When you dissolve it in water, the solution conducts electricity vigorously. What is the nature of X?', '["Polar covalent molecule","Metallic solid","Covalent network solid","Ionic lattice"]'::jsonb, 'D', 1, '0da769d3deb3', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A scientist discovers a material that conducts electricity in both the solid and liquid states and is highly malleable. What type of bonding is present?', '["Covalent","Metallic","Ionic","Dative"]'::jsonb, 'B', 1, '700cc9f5e578', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student compares NaCl and Cl₂. Both contain chlorine atoms. Why is chlorine present as ions in one substance but as molecules in the other?', '["Chlorine changes its atomic number","The bonding partner is different","Chlorine gains protons in NaCl","Chlorine loses neutrons in Cl₂"]'::jsonb, 'B', 1, '9ad201d2b37d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A metal atom loses two electrons while a non-metal atom gains two electrons. What is the ratio of ions in the resulting compound?', '["1 : 1","1 : 2","2 : 1","2 : 3"]'::jsonb, 'A', 1, '161f4ff36e9f', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You have two liquids: H₂O and CCl₄. You notice that NaCl dissolves in H₂O but not in CCl₄. Why?', '["CCl₄ is too viscous.","NaCl is covalent.","H₂O is polar and interacts with ions; CCl₄ is non-polar and cannot stabilize ions.","H₂O is a metal."]'::jsonb, 'C', 1, '462722462414', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom Z has an empty 2p orbital and forms a bond with NH₃, where both electrons are provided by the Nitrogen. What is this bond called?', '["Coordinate covalent bond","Ionic bond","Metallic bond","Hydrogen bond"]'::jsonb, 'A', 1, 'ae2a75e8bc64', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You add a substance to a beaker of water; the substance sinks and does not dissolve, and it does not conduct electricity. What kind of substance is it likely to be?', '["A salt","An ionic compound","A metal","A simple covalent molecule"]'::jsonb, 'D', 1, '957021894280', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A scientist labels a bond as "non-directional." Which type of bonding could this be?', '["Ionic or Metallic.","Covalent only.","Only metallic.","Only ionic."]'::jsonb, 'A', 1, '28888efa7eb4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why do ionic crystals shatter when struck by a hammer?', '["They become covalent.","The layers slide, and like-charged ions end up adjacent to each other, causing massive repulsion.","The electrons escape.","The metal atoms bend."]'::jsonb, 'B', 1, '02c48b4c9af7', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why can''t a simple covalent molecule like CH₄ conduct electricity?', '["It has no ions and no delocalized electrons.","It is too small.","It has no protons.","It is metallic."]'::jsonb, 'A', 1, 'c7d297c7e26d', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If an atom of Magnesium reacts with Chlorine, what happens to the energy level?', '["Energy remains constant.","The atom disappears.","Energy is absorbed.","Energy is released as the system reaches a more stable configuration."]'::jsonb, 'D', 1, '0831b137c2fd', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why are ionic compounds solids at room temperature?', '["They have weak bonds.","The electrostatic forces between ions are so strong that they lock them into a rigid, repeating lattice.","They are metals.","They have no bonds."]'::jsonb, 'B', 1, '08f8c4f9f699', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You find a substance that is a "giant" structure, very hard, and does not conduct electricity. What could it be?', '["Graphite","Sodium Chloride","Silicon Dioxide","Copper"]'::jsonb, 'C', 1, '1d02cda95a52', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why are delocalized electrons in metals considered "delocalized"?', '["They are not bound to any single atom and can move throughout the lattice.","They are lost.","They are in the nucleus.","They are in the inner shell."]'::jsonb, 'A', 1, 'ff83f086e0df', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom with six valence electrons reacts with hydrogen atoms. How many covalent bonds will it most likely form?', '["One","Two","Three","Four"]'::jsonb, 'B', 1, 'cc7f7476d364', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student notices that an ionic compound remains electrically neutral despite containing charged particles. Why?', '["Positive and negative charges balance each other","Electrons disappear during bonding","Only positive ions are present","Only negative ions are present"]'::jsonb, 'A', 1, '900bfe7c8811', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student argues that atoms bond because they want to increase their mass. Which observation best refutes this idea?', '["Bonding increases neutrons","Bonding creates new elements","Bonding increases the atomic number","Bonding changes electron arrangement, not nuclear composition"]'::jsonb, 'D', 1, '51f7cf5a8ea2', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom contributes both electrons in a shared pair while the other contributes none. Before bond formation, the second atom most likely had:', '["No valence electrons","A vacant orbital available for the pair","Excess neutrons","A positive nucleus only"]'::jsonb, 'B', 1, '5814e744d435', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student observes that chlorine forms Cl⁻ rather than Cl⁺ during ionic bond formation. The most reasonable explanation is that chlorine:', '["Easily loses seven electrons","Is a metal","Has one valence electron","Needs one electron for stability"]'::jsonb, 'D', 1, 'b7f734c6d3b4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An atom gains electrons during bond formation. Which quantity remains unchanged?', '["Electronic configuration","Atomic number","Charge","Number of electrons"]'::jsonb, 'B', 1, 'f391ee39dd6c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Element P has 2 valence electrons, and Element Q has 7 valence electrons. If they react, what is the most likely formula and bond type?', '["PQ₂, Covalent","P₂Q, Ionic","PQ₂, Ionic","PQ₇, Metallic"]'::jsonb, 'C', 1, '9c9dd4be0be3', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does the bond angle in NH₃ (107o) differ from the ideal tetrahedral angle (109.5o)?', '["The lone pair on Nitrogen exerts more repulsion on the bonding pairs than the bonding pairs do on each other.","NH₃ is an ionic compound.","Nitrogen has too many protons.","H atoms are too large."]'::jsonb, 'A', 1, '15ffcf3af2d9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following explains why NH₃ has a higher boiling point than PH₃?', '["NH₃ has stronger Van der Waals forces.","Nitrogen is more electronegative than Phosphorus, allowing NH₃ to form intermolecular Hydrogen bonds, while PH₃ cannot.","NH₃ is a larger molecule.","PH₃is ionic."]'::jsonb, 'B', 1, '459c81016489', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the molecule SF₆, the Sulfur atom is said to have an "expanded octet." How is this physically possible?', '["It is an ionic compound.","It has no bonds.","Sulfur uses its vacant 3d orbitals to accommodate more than 8 valence electrons.","It loses its nucleus."]'::jsonb, 'C', 1, 'ae092ea2c240', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which factor is the most significant in determining the "covalent character" of an ionic bond?', '["High charge and small size of the cation.","Large size of the cation.","Low electronegativity of the anion.","The color of the crystal."]'::jsonb, 'A', 1, '0a79990eb7f7', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following bonds is the most polar?', '["C-H","C-F","C-O","C-N"]'::jsonb, 'B', 1, '4e2c51bde498', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the bond energy of O₂ (double bond) not exactly twice the bond energy of O-O (single bond)?', '["Double bonds are always exactly double.","O₂ is ionic.","It depends on the color.","π-bonds are generally weaker than σ-bonds due to less effective orbital overlap, so they do not add linearly."]'::jsonb, 'D', 1, 'f7bdc5cb8ced', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following ions is most likely to show the highest degree of polarization in a bond?', '["Na⁺","Al³⁺","K⁺","Ca²⁺"]'::jsonb, 'B', 1, '88a1c6f43d24', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If electrons in a metallic bond were localized between specific atoms, metals would most likely lose their:', '["Color","Malleability","Atomic mass","Density"]'::jsonb, 'B', 1, 'fc8ab584a8d1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In an ionic crystal, each ion is surrounded by ions of opposite charge. This arrangement primarily serves to:', '["Reduce atomic number.","Increase neutron count.","Maximize electrostatic stability.","Form molecules."]'::jsonb, 'C', 1, 'bf4a9935c1a7', null);
